-- BORRADOR SOLO LECTURA. Requiere revisar resultados con visibilidad completa.
SELECT DATABASE() AS base_seleccionada,VERSION() AS servidor,CURRENT_USER() AS usuario_efectivo;
SELECT 'tablas nuevas InnoDB' AS comprobacion,IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('canecas_valoraciones_iniciales','canecas_capas_costo','canecas_gastos_posteriores') AND ENGINE='InnoDB')=3,'REVISAR','DETENER') AS resultado
UNION ALL SELECT 'columnas nuevas',IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME='canecas_compras' AND COLUMN_NAME IN ('precio_unitario_centavos','gastos_centavos','moneda')) OR (TABLE_NAME='canecas_productos' AND COLUMN_NAME IN ('precio_venta_referencia_centavos','precio_venta_referencia_moneda'))))=5,'REVISAR','DETENER')
UNION ALL SELECT 'triggers de protección',IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('can_compra_costos_inmutables','can_capa_costo_inmutable','can_capa_no_borrar','can_gasto_no_editar','can_gasto_no_borrar','can_valoracion_no_editar','can_valoracion_no_borrar'))=7,'REVISAR','DETENER');
SELECT e.tabla,e.columna,e.tipo,e.nulo,IF(c.COLUMN_NAME IS NOT NULL AND c.DATA_TYPE=e.tipo AND c.COLUMN_TYPE NOT LIKE '%unsigned%' AND c.IS_NULLABLE=e.nulo,'REVISAR','DETENER') AS resultado,c.COLUMN_TYPE,c.IS_NULLABLE
FROM (
 SELECT 'canecas_capas_costo' tabla,'id' columna,'bigint' tipo,'NO' nulo UNION ALL SELECT 'canecas_capas_costo','empresa_id','int','NO' UNION ALL SELECT 'canecas_capas_costo','producto_id','int','NO' UNION ALL SELECT 'canecas_capas_costo','ubicacion_id','int','NO' UNION ALL SELECT 'canecas_capas_costo','recepcion_id','int','YES' UNION ALL SELECT 'canecas_capas_costo','valoracion_id','bigint','YES' UNION ALL SELECT 'canecas_capas_costo','segmento','int','NO' UNION ALL SELECT 'canecas_capas_costo','cantidad_inicial','int','NO' UNION ALL SELECT 'canecas_capas_costo','cantidad_disponible','int','NO' UNION ALL SELECT 'canecas_capas_costo','costo_unitario_centavos','bigint','YES' UNION ALL SELECT 'canecas_capas_costo','moneda','char','YES'
 UNION ALL SELECT 'canecas_valoraciones_iniciales','id','bigint','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','empresa_id','int','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','producto_id','int','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','ubicacion_id','int','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','cantidad','int','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','costo_unitario_centavos','bigint','YES' UNION ALL SELECT 'canecas_valoraciones_iniciales','moneda','char','YES' UNION ALL SELECT 'canecas_valoraciones_iniciales','clave_operacion','char','NO' UNION ALL SELECT 'canecas_valoraciones_iniciales','creado_por','int','NO'
 UNION ALL SELECT 'canecas_gastos_posteriores','id','bigint','NO' UNION ALL SELECT 'canecas_gastos_posteriores','empresa_id','int','NO' UNION ALL SELECT 'canecas_gastos_posteriores','compra_id','int','NO' UNION ALL SELECT 'canecas_gastos_posteriores','importe_centavos','bigint','NO' UNION ALL SELECT 'canecas_gastos_posteriores','moneda','char','NO' UNION ALL SELECT 'canecas_gastos_posteriores','fecha_documento','date','NO' UNION ALL SELECT 'canecas_gastos_posteriores','estado','varchar','NO' UNION ALL SELECT 'canecas_gastos_posteriores','clave_operacion','char','NO' UNION ALL SELECT 'canecas_gastos_posteriores','creado_por','int','NO'
) e LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=e.tabla AND c.COLUMN_NAME=e.columna ORDER BY e.tabla,e.columna;
-- Un saldo sin capas es inventario pendiente de conciliar; una diferencia negativa es inconsistencia.
SELECT s.empresa_id,s.producto_id,s.ubicacion_id,s.fisico,COALESCE(SUM(c.cantidad_disponible),0) AS unidades_con_capa,s.fisico-COALESCE(SUM(c.cantidad_disponible),0) AS unidades_sin_capa FROM canecas_saldos s LEFT JOIN canecas_capas_costo c ON c.empresa_id=s.empresa_id AND c.producto_id=s.producto_id AND c.ubicacion_id=s.ubicacion_id GROUP BY s.empresa_id,s.producto_id,s.ubicacion_id,s.fisico HAVING s.fisico<>COALESCE(SUM(c.cantidad_disponible),0);
-- Las recepciones históricas previas pueden no tener capa; no se presupone costo cero.
SELECT r.empresa_id,r.id,r.cantidad,COALESCE(SUM(c.cantidad_inicial),0) AS cantidad_con_capa FROM canecas_recepciones r LEFT JOIN canecas_capas_costo c ON c.empresa_id=r.empresa_id AND c.recepcion_id=r.id WHERE r.estado='CONFIRMADA' GROUP BY r.empresa_id,r.id,r.cantidad HAVING r.cantidad<>COALESCE(SUM(c.cantidad_inicial),0);
-- Toda capa enlazada debe coincidir con su recepción o valoración y no cruzar empresas.
SELECT c.empresa_id,c.id AS capa,'recepcion' AS referencia FROM canecas_capas_costo c LEFT JOIN canecas_recepciones r ON r.empresa_id=c.empresa_id AND r.id=c.recepcion_id LEFT JOIN canecas_compras b ON b.empresa_id=r.empresa_id AND b.id=r.compra_id WHERE c.recepcion_id IS NOT NULL AND (r.id IS NULL OR b.id IS NULL OR c.producto_id<>b.producto_id OR c.ubicacion_id<>r.ubicacion_id OR r.estado<>'CONFIRMADA')
UNION ALL SELECT c.empresa_id,c.id,'valoracion' FROM canecas_capas_costo c LEFT JOIN canecas_valoraciones_iniciales v ON v.empresa_id=c.empresa_id AND v.id=c.valoracion_id WHERE c.valoracion_id IS NOT NULL AND (v.id IS NULL OR c.producto_id<>v.producto_id OR c.ubicacion_id<>v.ubicacion_id);
SELECT 'claves foráneas nuevas' AS comprobacion,IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_TYPE='FOREIGN KEY' AND CONSTRAINT_NAME IN ('fk_can_val_producto','fk_can_val_ubicacion','fk_can_val_usuario','fk_can_capa_producto','fk_can_capa_ubicacion','fk_can_capa_recepcion','fk_can_capa_valoracion','fk_can_gasto_compra','fk_can_gasto_usuario'))=9,'REVISAR','DETENER') AS resultado
UNION ALL SELECT 'restricciones CHECK',IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_TYPE='CHECK' AND CONSTRAINT_NAME IN ('chk_can_compra_costos','chk_can_precio_venta','chk_can_val_cantidad','chk_can_val_costo','chk_can_capa_fuente','chk_can_capa_cant','chk_can_capa_costo','chk_can_capa_moneda','chk_can_gasto_positivo','chk_can_gasto_estado'))=10,'REVISAR','DETENER');
SELECT e.tabla,e.columnas,IF(i.columnas IS NULL,'DETENER','REVISAR') resultado FROM (
 SELECT 'canecas_valoraciones_iniciales' tabla,'empresa_id,id' columnas UNION ALL SELECT 'canecas_valoraciones_iniciales','empresa_id,clave_operacion'
 UNION ALL SELECT 'canecas_capas_costo','empresa_id,id' UNION ALL SELECT 'canecas_capas_costo','empresa_id,recepcion_id,segmento' UNION ALL SELECT 'canecas_capas_costo','empresa_id,valoracion_id,segmento'
 UNION ALL SELECT 'canecas_gastos_posteriores','empresa_id,clave_operacion'
) e LEFT JOIN (
 SELECT TABLE_NAME,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX SEPARATOR ',') columnas FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND NON_UNIQUE=0 GROUP BY TABLE_NAME,INDEX_NAME
) i ON i.TABLE_NAME=e.tabla AND i.columnas=e.columnas ORDER BY e.tabla,e.columnas;
-- Los nombres no prueban el contenido de las restricciones: comparar definiciones antes de autorizar uso.
SELECT TRIGGER_NAME,EVENT_OBJECT_TABLE,ACTION_TIMING,EVENT_MANIPULATION,ACTION_STATEMENT FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('can_compra_costos_inmutables','can_capa_costo_inmutable','can_capa_no_borrar','can_gasto_no_editar','can_gasto_no_borrar','can_valoracion_no_editar','can_valoracion_no_borrar') ORDER BY TRIGGER_NAME;
SELECT TABLE_NAME,CONSTRAINT_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('canecas_valoraciones_iniciales','canecas_capas_costo','canecas_gastos_posteriores') AND REFERENCED_TABLE_NAME IS NOT NULL ORDER BY TABLE_NAME,CONSTRAINT_NAME,ORDINAL_POSITION;
SELECT CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN ('chk_can_compra_costos','chk_can_precio_venta','chk_can_val_cantidad','chk_can_val_costo','chk_can_capa_fuente','chk_can_capa_cant','chk_can_capa_costo','chk_can_capa_moneda','chk_can_gasto_positivo','chk_can_gasto_estado') ORDER BY CONSTRAINT_NAME;
